<script setup lang="ts">
import { onMounted, onBeforeUnmount, ref } from 'vue'
import { t } from '../i18n'
const props=defineProps<{csrfToken:string}>(),emit=defineEmits<{expired:[]}>()
const backup=ref({enabled:false,directory:'',intervalHours:24}),cdn=ref({enabled:false,baseUrl:'',maxAge:60})
type Job={id:string;kind:string;state:string;startedAt:number;finishedAt:number;total:number;completed:number;failed:number;bytes:number;destination?:string;message?:string}
const job=ref<Job>(),files=ref<{hash:string;bytes:number}[]>([]),deleteRemote=ref(false),busy=ref(false),error=ref(''),message=ref(''),loaded=ref(false)
let timer:ReturnType<typeof setInterval>|undefined,active=true
async function load(){try{const r=await fetch('/api/admin/operations');if(!active)return;if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);job.value=d.job;if(!loaded.value){backup.value=d.backup;cdn.value=d.cdn;loaded.value=true}}catch{if(active)error.value='暂时无法读取运维设置'}}
async function save(){busy.value=true;error.value='';message.value='';try{const r=await fetch('/api/admin/operations',{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:JSON.stringify({backup:backup.value,cdn:cdn.value})});if(r.status===401){emit('expired');return};if(!r.ok){const d=await r.json();throw new Error(d.error)};message.value='运维设置已保存。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function preview(){busy.value=true;error.value='';try{const r=await fetch('/api/admin/storage/orphans');if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);files.value=d.files;message.value=files.value.length?'':'没有可回收的孤立文件。'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function run(kind:'backup'|'sync'|'gc'){if(kind==='gc'&&!confirm(t('将回收 {count} 个孤立文件。执行时会再次检查引用，删除无法撤回。',{count:files.value.length})))return;busy.value=true;error.value='';message.value='';try{const r=await fetch('/api/admin/operations/'+kind,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':props.csrfToken},body:JSON.stringify({hashes:kind==='gc'?files.value.map(f=>f.hash):[],deleteRemote:deleteRemote.value})});if(r.status===401){emit('expired');return};const d=await r.json();if(!r.ok)throw new Error(d.error);job.value=d;if(kind==='gc')files.value=[]}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const stateNames:Record<string,string>={running:'执行中',completed:'已完成',completed_with_errors:'完成，但部分文件未处理',failed:'未完成'}
function bytes(n:number){return (n/1048576).toFixed(2)+' MiB'}
onMounted(()=>{void load();timer=setInterval(()=>{void load()},3000)})
onBeforeUnmount(()=>{active=false;if(timer)clearInterval(timer)})
</script>
<template><div class="operations-settings"><form class="settings-form" @submit.prevent="save"><fieldset :disabled="!loaded||busy"><section class="settings-section"><h3>{{ t('自动备份') }}</h3><label class="checkbox-label"><input v-model="backup.enabled" type="checkbox" />{{ t('启用定时备份') }}</label><label class="binding-field"><span>{{ t('独立备份目录') }}</span><input v-model="backup.directory" placeholder="D:\Backups\WishingSkin" :required="backup.enabled" /></label><label class="binding-field"><span>{{ t('间隔（小时）') }}</span><input v-model.number="backup.intervalHours" type="number" min="1" max="168" required /></label><p class="password-rule">{{ t('目录须已存在，且与材质目录独立。每次生成完整备份，不自动删除旧备份。设置密钥须单独保管。备份期间暂停新上传。') }}</p></section><section class="settings-section"><h3>CDN</h3><label class="checkbox-label"><input v-model="cdn.enabled" type="checkbox" />{{ t('启用公开材质 CDN') }}</label><label class="binding-field"><span>{{ t('CDN 地址') }}</span><input v-model="cdn.baseUrl" type="url" placeholder="https://cdn.example.com" :required="cdn.enabled" /></label><label class="binding-field"><span>{{ t('缓存上限（秒）') }}</span><input v-model.number="cdn.maxAge" type="number" min="1" max="60" required /></label><p class="password-rule">{{ t('仅加速已审核的公开材质。需将 /cdn/textures/ 回源到本站，并转发签名查询参数。下架后的缓存最多保留 60 秒。') }}</p></section><button class="primary-button">{{ t('保存运维设置') }}</button></fieldset></form><section class="settings-section"><h3>{{ t('存储维护') }}</h3><p class="password-rule">{{ t('旧材质同步需要启用对象存储插件。回收仅处理没有数据库记录且超过一小时的孤立文件，保留角色、衣柜和备份所需文件。') }}</p><div class="settings-actions"><button class="secondary-button" type="button" :disabled="busy||job?.state==='running'" @click="run('sync')">{{ t('同步旧材质到对象存储') }}</button><button class="secondary-button" type="button" :disabled="busy||job?.state==='running'||!backup.directory" @click="run('backup')">{{ t('立即备份（使用已保存设置）') }}</button><button class="secondary-button" type="button" :disabled="busy||job?.state==='running'" @click="preview">{{ t('预览可回收文件') }}</button></div><div v-if="files.length" class="orphan-preview"><p>{{ t('可回收 {count} 个文件，共 {bytes}。',{count:files.length,bytes:bytes(files.reduce((sum,f)=>sum+f.bytes,0))}) }}</p><details><summary>{{ t('文件清单') }}</summary><ul><li v-for="f in files" :key="f.hash"><code>{{ f.hash }}</code> {{ bytes(f.bytes) }}</li></ul></details><label class="checkbox-label"><input v-model="deleteRemote" type="checkbox" />{{ t('同时删除当前对象存储中同名的孤立副本') }}</label><button class="danger-button" type="button" :disabled="busy||job?.state==='running'" @click="run('gc')">{{ t('执行回收') }}</button></div><div v-if="job?.id" class="operation-status" role="status"><strong>{{ t(({sync:'材质同步',backup:'备份',gc:'存储回收'} as Record<string,string>)[job.kind]||job.kind) }} / {{ t(stateNames[job.state]||job.state) }}</strong><p>{{ t('完成 {done} / {total}，未处理 {failed}',{done:job.completed,total:job.total,failed:job.failed}) }}</p><p v-if="job.destination">{{ job.destination }}</p><p v-if="job.message">{{ t(job.message) }}</p></div></section><p v-if="error" class="form-error" role="alert">{{ t(error) }}</p><p v-if="message" class="action-success" role="status">{{ t(message) }}</p></div></template>
